/* ------------------------------------------------------------------ pacientes: seleção e cadastro */
const ptTags=p=>[ageMonths(p.birth||today())<120&&p.birth?['Criança','p3']:null,p.homecare?['Home care','p4']:null,p.pregnant?['Gestante','p6']:null,ageMonths(p.birth||today())>=720?['60+','p5']:null,p.ltc&&p.ltc.active?['Residente','p2']:null,p.aes?['Estética','p6']:null,!p.active?['Inativo','neutral']:null].filter(Boolean);
function PatientPicker({value,onChange,allowNew=true,id='pp'}){
  const {S}=useApp();const [q,setQ]=useState('');const [open,setOpen]=useState(false);const [nw,setNw]=useState(false);
  const p=value&&patOf(S,value);const t=q.trim().toLowerCase();
  const res=S.patients.filter(x=>x.active&&(!t||x.name.toLowerCase().includes(t)||(x.doc||'').toLowerCase().includes(t))).slice(0,7);
  if(p)return html`<div className="flex items-center gap-3 rounded-[18px] border border-line bg-panel2 p-3"><${Avatar} name=${p.name} size=${42}/>
    <div className="min-w-0 flex-1"><p className="truncate font-bold">${p.name}</p><p className="text-[12.5px] text-soft">${ageLabel(p.birth)}${p.birth?', nasc. '+F(p.birth,{day:'2-digit',month:'2-digit',year:'numeric'}):''}</p>
      <div className="mt-1 flex flex-wrap gap-1">${ptTags(p).map(([l,tn])=>html`<${Badge} key=${l} tone=${tn}>${l}<//>`)}</div></div>
    <${Btn} size="sm" v="ghost" onClick=${()=>{onChange('');setQ('')}}>Trocar<//></div>`;
  return html`<div className="relative"><div className="flex gap-2"><label className="flex h-11 flex-1 items-center gap-2 rounded-2xl bg-panel2 px-4"><${Icon} n="search" s=${16} className="text-faint"/>
      <input id=${id} className="min-w-0 flex-1 bg-transparent text-[15px] outline-none placeholder:text-faint" placeholder="Buscar paciente pelo nome ou documento" value=${q} onInput=${e=>{setQ(e.target.value);setOpen(true)}} onFocus=${()=>setOpen(true)} onBlur=${()=>setTimeout(()=>setOpen(false),150)}/></label>
    ${allowNew&&html`<${Btn} icon="plus" onClick=${()=>setNw(true)}>Novo<//>`}</div>
    ${open&&html`<div className="anim absolute left-0 right-0 top-12 z-30 max-h-72 overflow-y-auto rounded-[18px] border border-line bg-panel p-1.5 shadow-2xl">${res.length?res.map(x=>html`<button key=${x.id} onMouseDown=${e=>e.preventDefault()} onClick=${()=>{onChange(x.id);setOpen(false)}} className="flex w-full items-center gap-3 rounded-xl px-2.5 py-2 text-left hover:bg-panel2">
      <${Avatar} name=${x.name} size=${32}/><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">${x.name}</span><span className="block text-[12px] text-faint">${ageLabel(x.birth)}${x.allergies.length?' · alergia registrada':''}</span></span></button>`)
      :html`<p className="px-3 py-2.5 text-sm text-soft">Nenhum paciente encontrado.</p>`}</div>`}
    ${nw&&html`<${PatientForm} onClose=${()=>setNw(false)} onSaved=${id=>{onChange(id);setNw(false)}}/>`}</div>`;
}
function PatientForm({p,onClose,onSaved}){
  const {run}=useApp();const [f,setF]=useState(()=>p?{...p,allergies:p.allergies.join('; '),conditions:p.conditions.join('; ')}:{name:'',birth:'',sex:'',doc:'',phone:'',addr:'',region:'',guardian:'',allergies:'',conditions:'',homecare:false,pregnant:false});
  const set=k=>e=>setF({...f,[k]:e.target.type==='checkbox'?e.target.checked:e.target.value});
  const submit=()=>{const r=run((D,U)=>A.patientSave(D,U,f),p?'Cadastro atualizado.':'Paciente cadastrado.');if(r.ok)onSaved&&onSaved(r.data)};
  return html`<${Modal} open wide onClose=${onClose} title=${p?'Editar paciente':'Novo paciente'} desc="Use apenas dados fictícios na demonstração. Alergias e condições informadas aparecem como alerta em todo atendimento."
    footer=${html`<${Btn} onClick=${onClose}>Cancelar<//><${Btn} v="lime" onClick=${submit}>${p?'Salvar':'Cadastrar paciente'}<//>`}>
    <div className="grid gap-4 sm:grid-cols-6">
      <${Field} label="Nome completo" id="pt-n" className="sm:col-span-4"><input id="pt-n" className=${inputCls} value=${f.name} onInput=${set('name')}/><//>
      <${Field} label="Data de nascimento" id="pt-b" className="sm:col-span-2"><input id="pt-b" type="date" className=${inputCls} value=${f.birth} onChange=${set('birth')}/><//>
      <${Field} label="Sexo" id="pt-s" className="sm:col-span-2"><select id="pt-s" className=${inputCls} value=${f.sex} onChange=${set('sex')}><option value="">Não informado</option><option value="F">Feminino</option><option value="M">Masculino</option></select><//>
      <${Field} label="Documento (CNS ou CPF)" id="pt-d" className="sm:col-span-2"><input id="pt-d" className=${inputCls} value=${f.doc} onInput=${set('doc')}/><//>
      <${Field} label="Telefone" id="pt-t" className="sm:col-span-2"><input id="pt-t" className=${inputCls} value=${f.phone} onInput=${set('phone')}/><//>
      <${Field} label="Endereço" id="pt-a" className="sm:col-span-4"><input id="pt-a" className=${inputCls} value=${f.addr} onInput=${set('addr')}/><//>
      <${Field} label="Bairro ou região" id="pt-r" className="sm:col-span-2"><input id="pt-r" className=${inputCls} value=${f.region} onInput=${set('region')}/><//>
      <${Field} label="Responsável (se menor ou dependente)" id="pt-g" className="sm:col-span-6"><input id="pt-g" className=${inputCls} value=${f.guardian} onInput=${set('guardian')}/><//>
      <${Field} label="Alergias informadas" id="pt-al" hint="Separe por ponto e vírgula." className="sm:col-span-3"><input id="pt-al" className=${inputCls} value=${f.allergies} onInput=${set('allergies')}/><//>
      <${Field} label="Condições informadas" id="pt-c" hint="Separe por ponto e vírgula." className="sm:col-span-3"><input id="pt-c" className=${inputCls} value=${f.conditions} onInput=${set('conditions')}/><//>
      <div className="flex flex-wrap gap-2 sm:col-span-6">${[['homecare','Atendido em home care'],['pregnant','Gestante']].map(([k,l])=>html`<label key=${k} className=${cx('cursor-pointer rounded-full px-3.5 py-1.5 text-sm font-semibold',f[k]?'bg-lime text-onlime':'bg-panel2')}><input type="checkbox" className="sr-only" checked=${f[k]} onChange=${set(k)}/>${l}</label>`)}</div></div><//>`;
}

/* ------------------------------------------------------------------ vacinação */
const vacLots=(S,v)=>{const T=today();return S.lots.filter(l=>{const it=itemOf(S,l.item);return it&&it.vac===v&&!it.archived&&l.status==='disponivel'&&l.exp>=T&&l.qty>0}).sort((a,b)=>a.exp.localeCompare(b.exp))};
const VacChip=({v,dose,sub,onClick,active,st,small})=>{const V=VAC[v];return html`<button type="button" onClick=${onClick} disabled=${!onClick} className=${cx('relative flex min-w-0 flex-col rounded-2xl px-3 py-2 text-left text-onp transition enabled:hover:-translate-y-0.5 enabled:hover:shadow-md',PASTEL[V.c],active&&'ring-2 ring-ink ring-offset-2 ring-offset-panel',small?'py-1.5':'')}>
  <span className="truncate text-[13px] font-bold leading-tight">${V.n}</span>${dose&&html`<span className="truncate text-[11.5px] opacity-75">${dose}</span>`}${sub&&html`<span className="truncate text-[11px] opacity-70">${sub}</span>`}
  ${st&&st!=='prevista'&&st!=='condicional'&&html`<span className=${cx('absolute -right-1.5 -top-1.5 grid h-5 w-5 place-items-center rounded-full text-white ring-2 ring-panel',{aplicada:'bg-[#2f8a3c]',atrasada:'bg-[#d23a2f]',agora:'bg-[#2c5fd6]',janela:'bg-[#b8740a]'}[st])}><${Icon} n=${st==='aplicada'?'check':st==='atrasada'?'alert':st==='janela'?'x':'clock'} s=${11}/></span>`}</button>`};
function Vacinacao(){
  const {S,u,run,go,page}=useApp();const T=today();const apply=can(S,u,'vaccines.apply'),manage=can(S,u,'vaccines.manage');
  const stockVac=[...new Set(S.items.filter(i=>i.cat==='Vacina'&&i.vac&&!i.archived).map(i=>i.vac))];
  const empty={patient:page.patient||'',vac:page.vac||'',dose:'',lot:'',via:'',site:'',strategy:'Rotina',notes:'',prof:''};
  const [f,setF]=useState(empty);const [c,setC]=useState(null);const [reason,setReason]=useState('');
  const [fl,setFl]=useState('hoje');const [q,setQ]=useState('');const [det,setDet]=useState(null);const [cancel,setCancel]=useState(null);const [ext,setExt]=useState(false);
  const pt=f.patient&&patOf(S,f.patient);const lots=f.vac?vacLots(S,f.vac):[];const lot=f.lot||(lots[0]&&lots[0].id)||'';
  const via=f.via||(f.vac?VAC[f.vac].via:'');const sugg=pt?(childStatus(S,pt)||[]).flatMap(r=>r.items).filter(i=>(i.st==='agora'||i.st==='atrasada')&&stockVac.includes(i.v)):[];
  const pickVac=(v,dose)=>{setF({...f,vac:v,dose:dose||f.dose||'',lot:'',via:'',site:''});setC(null)};
  const submit=()=>{const r=run((D,U)=>A.immunize(D,U,{...f,lot,via,reason}),'Aplicação registrada. A dose saiu do estoque e entrou na caderneta do paciente.');
    if(r.ok){setF({...empty,patient:'',vac:''});setC(null);setReason('')}else if(r.checks)setC(r.checks)};
  const list=S.imm.filter(i=>i.origin!=='externa'&&(fl==='todas'||(fl==='hoje'?dkey(i.at)===T:dkey(i.at)>=addDays(T,-6)))&&(!q||patOf(S,i.patient).name.toLowerCase().includes(q.toLowerCase())));
  const profs=S.profs.filter(p=>p.active&&p.cat!=='medico');
  return html`<div className="space-y-5"><${PageHead} title="Vacinação" desc="Registro com paciente, vacina, dose, lote, via e local de aplicação. Cada registro baixa a dose do estoque e entra na caderneta do paciente."
    actions=${html`${apply&&html`<${Btn} icon="file" onClick=${()=>setExt(true)}>Transcrever caderneta<//>`}<${Btn} v="ink" icon="calcheck" onClick=${()=>go({page:'calendario'})}>Calendário vacinal<//>`}/>
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
      <${Kpi} icon="syringe" tone=${3} title="Aplicações" sub="Hoje" value=${S.imm.filter(i=>dkey(i.at)===T&&i.status==='registrado'&&i.origin!=='externa').length} detail="registradas nesta instituição"/>
      <${Kpi} icon="activity" tone=${4} title="Últimos 7 dias" sub="Aplicações" value=${S.imm.filter(i=>dkey(i.at)>=addDays(T,-6)&&i.status==='registrado'&&i.origin!=='externa').length}/>
      <${Kpi} icon="clock" tone=${1} title="Lotes vencendo" sub="Em 30 dias" value=${S.lots.filter(l=>(itemOf(S,l.item)||{}).cat==='Vacina'&&lotStatus(S,l)==='vencendo'&&l.qty>0).length} onClick=${()=>go({page:'estoque'})}/>
      <${Kpi} icon="lock" tone=${6} title="Lotes bloqueados" sub="Vencidos ou em avaliação" value=${S.lots.filter(l=>(itemOf(S,l.item)||{}).cat==='Vacina'&&(l.status!=='disponivel'||l.exp<T)&&l.qty>0).length} onClick=${()=>go({page:'temperatura'})}/></div>
    <div className="grid gap-5 xl:grid-cols-[1.1fr_1fr]">
      ${apply?html`<${Card} title="Registrar aplicação" sub="Só aparecem lotes válidos e liberados." icon="syringe" tone=${3}>
        <div className="space-y-5">
          <section><p className="mb-2 text-[13px] font-bold text-soft">1. Paciente</p><${PatientPicker} id="im-p" value=${f.patient} onChange=${id=>{setF({...f,patient:id});setC(null)}}/>
            ${pt&&pt.allergies.length>0&&html`<p className="mt-2 flex items-start gap-2 rounded-2xl bg-dangerbg px-3.5 py-2.5 text-sm font-semibold text-danger"><${Icon} n="alert" s=${16} className="mt-0.5 shrink-0"/>Alergias registradas: ${pt.allergies.join(', ')}. Confira antes de aplicar.</p>`}
            ${pt&&html`<div className="mt-2 flex flex-wrap items-center gap-2 text-[13px]"><button className="font-semibold text-skyink hover:underline" onClick=${()=>go({page:'paciente',id:pt.id})}>Abrir prontuário e caderneta</button>
              ${sugg.length>0&&html`<span className="text-faint">·</span><span className="text-soft">Pelo calendário:</span>${sugg.slice(0,5).map(i=>html`<button key=${i.v+i.dose} onClick=${()=>pickVac(i.v,i.dose)} className=${cx('rounded-full px-2.5 py-1 text-[12px] font-bold text-onp',PASTEL[VAC[i.v].c])}>${VAC[i.v].n}, ${i.dose}${i.st==='atrasada'?' (verificar atraso)':''}</button>`)}`}</div>`}</section>
          <section><p className="mb-2 text-[13px] font-bold text-soft">2. Vacina</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-3">${stockVac.map(v=>{const n=vacLots(S,v).reduce((t,l)=>t+l.qty,0);return html`<${VacChip} key=${v} v=${v} sub=${n?n+' doses liberadas':'Sem lote liberado'} active=${f.vac===v} onClick=${n?()=>pickVac(v):null}/>`})}</div></section>
          ${f.vac&&html`<section className="anim space-y-4"><p className="text-[13px] font-bold text-soft">3. Dose, lote, via e local</p>
            <div className="grid gap-3 sm:grid-cols-2">
              <${Field} label="Dose" id="im-d"><select id="im-d" className=${inputCls} value=${f.dose} onChange=${e=>setF({...f,dose:e.target.value})}><option value="">Selecione</option>${DOSES.map(x=>html`<option key=${x}>${x}</option>`)}</select><//>
              <${Field} label="Lote" id="im-l"><select id="im-l" className=${inputCls} value=${lot} onChange=${e=>setF({...f,lot:e.target.value})}>${lots.map(l=>html`<option key=${l.id} value=${l.id}>${l.lot}, val. ${F(l.exp,{day:'2-digit',month:'2-digit',year:'2-digit'})}, ${l.qty} doses, ${unitOf(S,l.unit).name}</option>`)}</select><//>
              <${Field} label="Via de administração" id="im-via" hint=${'Recomendada no calendário: '+VAC[f.vac].via.toLowerCase()}><select id="im-via" className=${inputCls} value=${via} onChange=${e=>setF({...f,via:e.target.value,site:''})}>${VIAS.map(x=>html`<option key=${x}>${x}</option>`)}</select><//>
              <${Field} label="Estratégia" id="im-st"><select id="im-st" className=${inputCls} value=${f.strategy} onChange=${e=>setF({...f,strategy:e.target.value})}>${['Rotina','Campanha','Particular','Intensificação','Bloqueio'].map(x=>html`<option key=${x}>${x}</option>`)}</select><//></div>
            <div><p className="mb-1.5 text-[13px] font-semibold text-soft">Local de aplicação</p><div className="flex flex-wrap gap-1.5" role="radiogroup" aria-label="Local de aplicação">${SITES[via].map(x=>html`<button key=${x} role="radio" aria-checked=${f.site===x} onClick=${()=>setF({...f,site:x})} className=${cx('rounded-full px-3 py-1.5 text-[13px] font-semibold transition',f.site===x?'bg-navy text-onnavy':'bg-panel2 hover:bg-p3 hover:text-onp')}>${x}</button>`)}</div>
              <p className="mt-1 text-xs text-faint">Escolha conforme a idade e as normas técnicas vigentes. O sistema registra o que foi feito.</p></div>
            ${!u.prof&&html`<${Field} label="Profissional que aplicou" id="im-pr"><select id="im-pr" className=${inputCls} value=${f.prof} onChange=${e=>setF({...f,prof:e.target.value})}><option value="">Selecione</option>${profs.map(p=>html`<option key=${p.id} value=${p.id}>${p.name}</option>`)}</select><//>`}
            <${Field} label="Observações (opcional)" id="im-o"><textarea id="im-o" className=${inputCls+' min-h-[56px]'} value=${f.notes} onInput=${e=>setF({...f,notes:e.target.value})} placeholder="Ex.: paciente permaneceu em observação por 15 minutos"></textarea><//>
            <div className="rounded-[18px] bg-panel2 p-3.5 text-[13px]"><p className="font-bold">${VAC[f.vac].full}</p><p className="mt-1 text-soft">Previne: ${VAC[f.vac].dz}.</p><p className="mt-1 text-soft">Via no calendário técnico: ${VAC[f.vac].via}${VAC[f.vac].vol?', '+VAC[f.vac].vol:''}.</p>
              <button className="mt-1.5 font-semibold text-skyink hover:underline" onClick=${()=>go({page:'calendario',vac:f.vac})}>Ver no calendário vacinal</button></div>
            ${c&&html`<${Override} c=${c} reason=${reason} setReason=${setReason}/>`}
            <div className="flex flex-wrap items-center justify-between gap-3"><p className="text-[13px] text-soft">${u.prof?'Aplicado por: '+u.name:''}</p>
              <${Btn} v="lime" size="lg" icon="check" onClick=${submit} disabled=${!f.patient||!f.dose||!f.site||!lot||(c&&!reason.trim())||(!u.prof&&!f.prof)}>${c?'Justificar e registrar':'Registrar aplicação'}<//></div></section>`}
        </div><//>`
      :html`<${Card} title="Registro de aplicação"><p className="text-sm text-soft">Seu perfil consulta, mas não registra aplicações.</p><//>`}
      <${Card} title="Aplicações" icon="activity" tone=${4} action=${html`<${Seg} size="sm" items=${[['hoje','Hoje'],['semana','7 dias'],['todas','Todas']]} value=${fl} onChange=${setFl}/>`}>
        <input className=${inputCls+' mb-3'} placeholder="Filtrar por paciente" aria-label="Filtrar por paciente" value=${q} onInput=${e=>setQ(e.target.value)}/>
        ${list.length===0?html`<${Empty} title="Nenhuma aplicação neste filtro"/>`:html`<ul className="space-y-2">${list.slice(0,30).map(i=>{const p=patOf(S,i.patient),V=VAC[i.vac];return html`<li key=${i.id} className=${cx('rounded-[18px] border border-line/70 p-3',i.status==='cancelado'&&'opacity-50')}>
          <div className="flex items-start gap-3"><span className=${cx('grid h-11 w-11 shrink-0 place-items-center rounded-2xl text-onp',PASTEL[V.c])}><${Icon} n="syringe" s=${18}/></span>
            <button className="min-w-0 flex-1 text-left" onClick=${()=>setDet(i)}><p className="truncate text-sm font-bold">${p.name}</p><p className="truncate text-[12.5px] text-soft">${V.n}, ${i.dose} · ${i.via}, ${i.site.toLowerCase()}</p>
              <p className="text-[12px] text-faint">${F(i.at,{day:'2-digit',month:'2-digit'})} ${hm(i.at)} · lote ${i.lot?lotOf(S,i.lot).lot:'—'} · ${i.prof?profOf(S,i.prof).name.split(' ')[0]:''}</p></button>
            ${i.status==='cancelado'?html`<${Badge}>Estornado<//>`:html`<${Badge} tone="p4">${i.strategy}<//>`}</div></li>`})}</ul>`}<//></div>
    ${det&&html`<${Modal} open onClose=${()=>setDet(null)} title=${'Aplicação de '+VAC[det.vac].n} desc=${patOf(S,det.patient).name}
      footer=${html`${manage&&det.status==='registrado'&&html`<${Btn} v="danger" className="mr-auto" onClick=${()=>{setCancel(det);setDet(null)}}>Cancelar aplicação<//>`}<${Btn} onClick=${()=>go({page:'paciente',id:det.patient})}>Abrir prontuário<//><${Btn} v="lime" onClick=${()=>setDet(null)}>Fechar<//>`}>
      <dl className="grid gap-2 sm:grid-cols-2">${[['Vacina',VAC[det.vac].full],['Dose',det.dose],['Data e hora',F(det.at,{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})],['Lote',det.lot?`${lotOf(S,det.lot).lot} (val. ${D2(lotOf(S,det.lot).exp)})`:'—'],['Via',det.via],['Local de aplicação',det.site],['Profissional',det.prof?profOf(S,det.prof).name:'—'],['Unidade',det.unit?unitOf(S,det.unit).name:'—'],['Estratégia',det.strategy],['Observações',det.notes||'Nenhuma']].concat(det.status==='cancelado'?[['Cancelamento',det.cancelReason]]:[]).map(([k,v])=>html`<div key=${k} className="rounded-[16px] bg-panel2 px-3.5 py-2.5"><dt className="text-[12px] text-faint">${k}</dt><dd className="text-sm font-semibold">${v}</dd></div>`)}</dl><//>`}
    <${Confirm} open=${!!cancel} title="Cancelar aplicação" desc=${cancel?`${patOf(S,cancel.patient).name}, ${VAC[cancel.vac].n}. A dose volta ao lote como estorno e o registro fica no histórico.`:''} okLabel="Cancelar aplicação" needReason onClose=${()=>setCancel(null)} onOk=${r=>{const x=run((D,U)=>A.immunizeCancel(D,U,cancel.id,r),'Aplicação cancelada e estoque estornado.');if(x.ok)setCancel(null)}}/>
    ${ext&&html`<${ExternalDose} onClose=${()=>setExt(false)}/>`}</div>`;
}
function ExternalDose({patient,onClose}){
  const {run}=useApp();const [f,setF]=useState({patient:patient||'',vac:'',dose:'',date:'',place:'',lotText:''});
  return html`<${Modal} open wide onClose=${onClose} title="Transcrever dose da caderneta" desc="Para doses aplicadas em outro serviço. Não mexe no estoque e fica marcada como transcrição."
    footer=${html`<${Btn} onClick=${onClose}>Cancelar<//><${Btn} v="lime" onClick=${()=>{const r=run((D,U)=>A.immExternal(D,U,f),'Dose transcrita para a caderneta.');if(r.ok)onClose()}}>Transcrever<//>`}>
    <div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><p className="mb-1.5 text-[13px] font-semibold text-soft">Paciente</p><${PatientPicker} id="ex-p" value=${f.patient} onChange=${id=>setF({...f,patient:id})} allowNew=${false}/></div>
      <${Field} label="Vacina" id="ex-v"><select id="ex-v" className=${inputCls} value=${f.vac} onChange=${e=>setF({...f,vac:e.target.value})}><option value="">Selecione</option>${Object.entries(VAC).map(([k,v])=>html`<option key=${k} value=${k}>${v.full}</option>`)}</select><//>
      <${Field} label="Dose" id="ex-d"><select id="ex-d" className=${inputCls} value=${f.dose} onChange=${e=>setF({...f,dose:e.target.value})}><option value="">Selecione</option>${DOSES.map(x=>html`<option key=${x}>${x}</option>`)}</select><//>
      <${Field} label="Data da aplicação" id="ex-dt"><input id="ex-dt" type="date" className=${inputCls} value=${f.date} onChange=${e=>setF({...f,date:e.target.value})}/><//>
      <${Field} label="Lote (se constar)" id="ex-l"><input id="ex-l" className=${inputCls} value=${f.lotText} onInput=${e=>setF({...f,lotText:e.target.value})}/><//>
      <${Field} label="Onde foi aplicada" id="ex-pl" className="sm:col-span-2"><input id="ex-pl" className=${inputCls} placeholder="Ex.: UBS Jardim Aurélia (conforme a caderneta)" value=${f.place} onInput=${e=>setF({...f,place:e.target.value})}/><//></div><//>`;
}

/* ------------------------------------------------------------------ calendário vacinal */
function CalendarioVacinal(){
  const {S,u,go,page}=useApp();const [grp,setGrp]=useState('crianca');const [q,setQ]=useState('');const [sel,setSel]=useState(page.vac||null);const [pid,setPid]=useState('');
  const G=CAL_GROUPS.find(g=>g.id===grp);const t=q.trim().toLowerCase();const match=v=>!t||(VAC[v].full+' '+VAC[v].dz).toLowerCase().includes(t);
  const kids=S.patients.filter(p=>p.active&&p.birth&&ageMonths(p.birth)<120);const pt=pid&&patOf(S,pid);const status=pt?childStatus(S,pt):null;
  const stOf=(v,dose)=>{if(!status)return null;for(const r of status)for(const i of r.items)if(i.v===v&&i.dose===dose)return i;return null};
  const am=pt?ageMonths(pt.birth):null;const sum=status?status.flatMap(r=>r.items).filter(i=>i.core).reduce((m,i)=>(m[i.st]=(m[i.st]||0)+1,m),{}):null;
  const next=status?status.flatMap(r=>r.items.map(i=>({...i,age:r.age}))).filter(i=>i.core&&i.st==='prevista').slice(0,4):[];
  const where=v=>[...CAL_CHILD.flatMap(r=>r.items.filter(i=>i[0]===v).map(i=>['Criança',r.age+': '+i[1]+(i[3]?' ('+i[3]+')':'')])),...CAL_GROUPS.filter(g=>g.rows).flatMap(g=>g.rows.filter(r=>r[0]===v).map(r=>[g.t,r[1]+(r[2]?' · '+r[2]:'')]))];
  const V=sel&&VAC[sel];
  return html`<div className="space-y-5">
    <section className="relative overflow-hidden rounded-[28px] p-6 text-onp sm:p-8" style=${{background:'linear-gradient(120deg,rgb(var(--c-p3)),rgb(var(--c-p2)) 55%,rgb(var(--c-p4)))'}}>
      <div className="relative z-10 grid gap-5 lg:grid-cols-[1fr_auto] lg:items-end"><div><p className="inline-flex items-center gap-2 rounded-full bg-white/70 px-3 py-1 text-[12px] font-bold"><${Icon} n="calcheck" s=${13}/>Atualizado: ${CAL_SRC.updated}</p>
        <h1 className="mt-3 text-[30px] font-semibold leading-[1.05] tracking-tight sm:text-[44px]">Calendário Nacional<br/>de Vacinação 2026</h1>
        <p className="mt-2 max-w-xl text-[14.5px] opacity-80">Consulta rápida por idade e grupo, com a situação da caderneta de cada criança. Fonte: ${CAL_SRC.label}. Confira sempre a instrução normativa vigente.</p>
        <div className="mt-4 flex flex-wrap gap-2"><a href=${CAL_SRC.url} target="_blank" rel="noopener" className="inline-flex h-10 items-center gap-2 rounded-full bg-[#111318] px-5 text-sm font-bold text-white hover:opacity-90">Instrução normativa 2026<${Icon} n="ur" s=${14}/></a>
          <a href=${CAL_SRC.url2} target="_blank" rel="noopener" className="inline-flex h-10 items-center gap-2 rounded-full bg-white/75 px-5 text-sm font-bold hover:bg-white">Calendário técnico da criança<${Icon} n="ur" s=${14}/></a></div></div>
        <div className="w-full rounded-[22px] bg-white/70 p-4 backdrop-blur lg:w-[320px]"><label htmlFor="cv-p" className="text-[12.5px] font-bold">Conferir a caderneta de uma criança</label>
          <select id="cv-p" className="mt-1.5 block h-11 w-full rounded-2xl bg-white px-3 text-sm font-semibold text-[#15171c]" value=${pid} onChange=${e=>{setPid(e.target.value);setGrp('crianca')}}><option value="">Selecione</option>${kids.map(p=>html`<option key=${p.id} value=${p.id}>${p.name} (${ageLabel(p.birth)})</option>`)}</select>
          ${sum&&html`<div className="mt-3 grid grid-cols-3 gap-2 text-center">${[['aplicada','Aplicadas','#2f8a3c'],['atrasada','Verificar','#d23a2f'],['agora','Indicadas','#2c5fd6']].map(([k,l,c])=>html`<div key=${k} className="rounded-xl bg-white px-1 py-2"><p className="text-[22px] font-semibold leading-none" style=${{color:c}}>${sum[k]||0}</p><p className="text-[11px] font-semibold opacity-70">${l}</p></div>`)}</div>`}</div></div>
      <svg className="pointer-events-none absolute -right-10 -top-10 h-64 w-64 opacity-30" viewBox="0 0 200 200" aria-hidden="true"><circle cx="100" cy="100" r="90" fill="none" stroke="white" strokeWidth="18" strokeDasharray="30 18"/></svg></section>
    <div className="no-scrollbar flex gap-2 overflow-x-auto pb-1">${CAL_GROUPS.map(g=>html`<button key=${g.id} onClick=${()=>setGrp(g.id)} className=${cx('flex shrink-0 items-center gap-3 rounded-[20px] px-4 py-3 text-left transition',grp===g.id?'bg-navy text-onnavy shadow-lg':'card-sh bg-panel hover:-translate-y-0.5')}>
      <span className=${cx('grid h-10 w-10 place-items-center rounded-xl text-onp',PASTEL[g.c])}><${Icon} n=${g.id==='crianca'?'baby':g.id==='gestante'?'heart':g.id==='saude'?'shield':'users'} s=${18}/></span><span><span className="block text-sm font-bold">${g.t}</span><span className="block text-[12px] opacity-70">${g.sub}</span></span></button>`)}</div>
    <div className="grid gap-5 xl:grid-cols-[1fr_360px]">
      <${Card} title=${G.t+', '+G.sub.toLowerCase()} icon=${grp==='crianca'?'baby':'users'} tone=${G.c} action=${html`<input className=${inputCls+' h-10 w-56 py-1.5'} placeholder="Buscar vacina ou doença" aria-label="Buscar vacina" value=${q} onInput=${e=>setQ(e.target.value)}/>`}>
        ${G.child?html`<ol className="relative ml-2 border-l-2 border-dashed border-line pl-6">${CAL_CHILD.map(r=>{const items=r.items.filter(i=>match(i[0]));if(!items.length)return null;const here=am!=null&&am>=r.m&&am<(CAL_CHILD[CAL_CHILD.indexOf(r)+1]||{m:999}).m;
          return html`<li key=${r.age} className="relative pb-6 last:pb-0"><span className=${cx('absolute -left-[33px] top-1 grid h-4 w-4 place-items-center rounded-full ring-4 ring-panel',here?'bg-lime':'bg-ink')}></span>
            <div className="mb-2 flex flex-wrap items-center gap-2"><h3 className="text-[17px] font-semibold tracking-tight">${r.age}</h3>${here&&html`<${Badge} tone="lime">Idade atual de ${pt.name.split(' ')[0]}<//>`}${pt&&html`<span className="text-[12px] text-faint">${F(addMonthsKey(pt.birth,r.m),{day:'2-digit',month:'2-digit',year:'numeric'})}</span>`}</div>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-4">${items.map(([v,dose,core,note])=>{const st=stOf(v,dose);return html`<${VacChip} key=${v+dose} v=${v} dose=${dose} sub=${st?CST[st.st][0]+(st.rec?' em '+D2(st.rec.at):''):note} st=${st&&st.st} active=${sel===v} onClick=${()=>setSel(v)}/>`})}</div></li>`})}</ol>`
        :html`<div className="grid gap-3 md:grid-cols-2">${G.rows.filter(r=>match(r[0])).map(([v,doses,when])=>html`<button key=${v} onClick=${()=>setSel(v)} className=${cx('flex items-stretch gap-3 overflow-hidden rounded-[18px] border border-line/70 bg-panel text-left transition hover:-translate-y-0.5 hover:shadow-md',sel===v&&'ring-2 ring-ink')}>
            <span className=${cx('w-2 shrink-0',PASTEL[VAC[v].c])}></span><span className="min-w-0 py-3 pr-3"><span className="block font-bold">${VAC[v].full}</span><span className="mt-0.5 block text-[13px] font-semibold text-soft">${doses}</span>${when&&html`<span className="mt-0.5 block text-[12.5px] text-faint">${when}</span>`}</span></button>`)}</div>`}
        <div className="mt-6 rounded-[18px] bg-panel2 p-4"><p className="mb-2 flex items-center gap-2 text-sm font-bold"><${Icon} n="info" s=${15}/>Notas do calendário</p><ul className="space-y-1.5 text-[13px] text-soft">${CAL_NOTES.map((n,i)=>html`<li key=${i} className="flex gap-2"><span className="mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full bg-faint"></span>${n}</li>`)}</ul></div><//>
      <div className="space-y-5 xl:sticky xl:top-24 xl:self-start">
        ${V?html`<section className=${cx('anim rounded-[24px] p-5 text-onp',PASTEL[V.c])} key=${sel}><div className="flex items-start justify-between gap-3"><div><p className="text-[12px] font-bold uppercase tracking-wider opacity-60">Ficha de consulta</p><h2 className="mt-1 text-[22px] font-semibold leading-tight">${V.full}</h2></div><button onClick=${()=>setSel(null)} className="grid h-8 w-8 place-items-center rounded-full bg-white/60" aria-label="Fechar ficha"><${Icon} n="x" s=${14}/></button></div>
          <dl className="mt-4 space-y-2 text-sm">${[['Previne',V.dz],['Via',V.via],['Volume',V.vol||'Conforme bula do produto']].map(([k,v])=>html`<div key=${k} className="rounded-2xl bg-white/65 px-3.5 py-2.5"><dt className="text-[11.5px] font-bold opacity-60">${k}</dt><dd className="font-semibold">${v}</dd></div>`)}</dl>
          <p className="mt-4 text-[12px] font-bold uppercase tracking-wider opacity-60">No calendário</p><ul className="mt-1.5 space-y-1">${where(sel).map(([g,t],i)=>html`<li key=${i} className="rounded-xl bg-white/50 px-3 py-1.5 text-[13px]"><b>${g}:</b> ${t}</li>`)}</ul>
          ${can(S,u,'vaccines.apply')&&html`<button onClick=${()=>go({page:'vacinacao',vac:sel,patient:pid||undefined})} className="mt-4 h-10 w-full rounded-full bg-[#111318] text-sm font-bold text-white hover:opacity-90">Registrar aplicação</button>`}</section>`
        :html`<${Card} title="Ficha da vacina" icon="info" tone=${2}><p className="text-sm text-soft">Toque em uma vacina para ver doenças evitadas, via, volume e em que idades ela aparece.</p><//>`}
        ${pt&&html`<${Card} title=${'Próximas doses de '+pt.name.split(' ')[0]} icon="clock" tone=${1}>${next.length?html`<ul className="space-y-1.5">${next.map(i=>html`<li key=${i.v+i.dose} className="flex items-center gap-3 rounded-2xl bg-panel2 px-3 py-2"><span className=${cx('h-8 w-1.5 rounded-full',PASTEL[VAC[i.v].c])}></span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-bold">${VAC[i.v].n}, ${i.dose}</span><span className="text-[12px] text-faint">${i.age}</span></span><span className="text-[12.5px] font-semibold">${F(i.due,{day:'2-digit',month:'2-digit',year:'2-digit'})}</span></li>`)}</ul>`:html`<p className="text-sm text-soft">Sem doses previstas do calendário de rotina até 4 anos.</p>`}
          <button className="mt-3 text-sm font-semibold text-skyink hover:underline" onClick=${()=>go({page:'paciente',id:pt.id})}>Abrir caderneta completa</button><//>`}
        <p className="px-1 text-[12px] text-faint">A conferência automática compara os registros feitos nesta instituição e as doses transcritas. Indicação, contraindicação e esquemas especiais (CRIE) são decisão do profissional.</p></div></div></div>`;
}

/* ------------------------------------------------------------------ prontuário */
function Prontuario(){
  const {S,u,go,page}=useApp();const [q,setQ]=useState('');const [fl,setFl]=useState('todos');const [nw,setNw]=useState(false);
  useEffect(()=>{if(page.nw&&can(S,u,'records.write'))setNw(true)},[page]);
  const last=id=>{const d=[...S.imm.filter(i=>i.patient===id).map(i=>i.at),...S.evol.filter(e=>e.patient===id).map(e=>e.at),...S.procs.filter(x=>x.patient===id&&x.doneAt).map(x=>x.doneAt)].sort().pop();return d};
  const rows=S.patients.filter(p=>(fl==='inativos'?!p.active:p.active)&&(fl==='todos'||fl==='inativos'||(fl==='criancas'&&p.birth&&ageMonths(p.birth)<120)||(fl==='home'&&p.homecare)||(fl==='gestantes'&&p.pregnant))&&(!q||(p.name+' '+p.doc).toLowerCase().includes(q.toLowerCase()))).sort((a,b)=>a.name.replace(/^(Sr\.|Dona)\s/,'').localeCompare(b.name.replace(/^(Sr\.|Dona)\s/,'')));
  return html`<div className="space-y-5"><${PageHead} title="Prontuário eletrônico" desc="Pacientes, caderneta de vacinação, evoluções e procedimentos. Cada acesso fica registrado." actions=${can(S,u,'records.write')&&html`<${Btn} v="lime" icon="plus" onClick=${()=>setNw(true)}>Novo paciente<//>`}/>
    <div className="flex flex-wrap items-center gap-2"><${Seg} size="sm" items=${[['todos','Todos'],['criancas','Crianças'],['home','Home care'],['gestantes','Gestantes'],['inativos','Inativos']]} value=${fl} onChange=${setFl}/>
      <input className=${inputCls+' card-sh h-10 bg-panel py-1.5 sm:ml-auto sm:w-72'} placeholder="Buscar por nome ou documento" aria-label="Buscar paciente" value=${q} onInput=${e=>setQ(e.target.value)}/></div>
    ${rows.length===0?html`<${Empty} title="Nenhum paciente neste filtro"/>`:html`<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">${rows.map(p=>{const l=last(p.id);return html`<button key=${p.id} onClick=${()=>go({page:'paciente',id:p.id})} className="group card-sh flex flex-col rounded-[22px] bg-panel p-4 text-left transition hover:-translate-y-0.5 hover:shadow-lg">
      <div className="flex items-start gap-3"><${Avatar} name=${p.name} size=${48}/><div className="min-w-0 flex-1"><p className="truncate font-bold">${p.name}</p><p className="text-[13px] text-soft">${ageLabel(p.birth)}${p.sex?', '+(p.sex==='F'?'feminino':'masculino'):''}</p>
        <div className="mt-1.5 flex flex-wrap gap-1">${ptTags(p).map(([t,tn])=>html`<${Badge} key=${t} tone=${tn}>${t}<//>`)}</div></div><${Icon} n="ur" className="text-faint group-hover:text-ink"/></div>
      ${p.allergies.length>0&&html`<p className="mt-3 flex items-center gap-1.5 truncate rounded-xl bg-dangerbg px-2.5 py-1.5 text-[12px] font-semibold text-danger"><${Icon} n="alert" s=${13} className="shrink-0"/>Alergia: ${p.allergies.join(', ')}</p>`}
      <div className="mt-auto flex items-center gap-3 pt-3 text-[12px] text-faint"><span className="inline-flex items-center gap-1"><${Icon} n="syringe" s=${13}/>${S.imm.filter(i=>i.patient===p.id&&i.status==='registrado').length}</span><span className="inline-flex items-center gap-1"><${Icon} n="file" s=${13}/>${S.evol.filter(e=>e.patient===p.id).length}</span><span className="inline-flex items-center gap-1"><${Icon} n="clip" s=${13}/>${S.procs.filter(x=>x.patient===p.id).length}</span>
        <span className="ml-auto">${l?'Último registro '+D2(l):'Sem registros'}</span></div></button>`})}</div>`}
    ${nw&&html`<${PatientForm} onClose=${()=>setNw(false)} onSaved=${id=>{setNw(false);go({page:'paciente',id})}}/>`}</div>`;
}
const EV_KIND=['Evolução de enfermagem','Atendimento','Orientação','Observação'];
function PacienteDetail({id}){
  const {S,u,run,go}=useApp();const p=patOf(S,id);const [tab,setTab]=useState('tempo');const [edit,setEdit]=useState(false);const [del,setDel]=useState(false);const [ext,setExt]=useState(false);
  const [ev,setEv]=useState({kind:EV_KIND[0],text:''});const [ad,setAd]=useState(null);const [adT,setAdT]=useState('');
  useEffect(()=>{if(p)run((D,U)=>A.recordView(D,U,id))},[id]);
  if(!p)return html`<${Empty} title="Paciente não encontrado"/>`;
  if(!can(S,u,'records.view'))return html`<${Empty} title="Sem acesso ao prontuário">Seu perfil não tem permissão para ver prontuários.<//>`;
  const imm=S.imm.filter(i=>i.patient===id).sort((a,b)=>b.at.localeCompare(a.at));const evol=S.evol.filter(e=>e.patient===id).sort((a,b)=>b.at.localeCompare(a.at));
  const procs=S.procs.filter(x=>x.patient===id).sort((a,b)=>(b.date+b.start).localeCompare(a.date+a.start));const visits=S.visits.filter(v=>v.patient===id);
  const access=S.audit.filter(a=>a.ref===id&&a.entity==='patient');const status=childStatus(S,p);const write=can(S,u,'records.write');
  const tl=[...imm.map(i=>({at:i.at,k:i.id,ic:'syringe',tn:VAC[i.vac].c,t:`${VAC[i.vac].n}, ${i.dose}`,d:i.origin==='externa'?`Transcrita da caderneta: ${i.place}`:`${i.via}, ${i.site.toLowerCase()}, lote ${i.lot?lotOf(S,i.lot).lot:'—'}`,by:i.prof?profOf(S,i.prof).name:i.by,off:i.status==='cancelado'})),
    ...evol.map(e=>({at:e.at,k:e.id,ic:'file',tn:2,t:e.kind,d:e.text,by:e.author})),
    ...procs.filter(x=>x.doneAt||x.status==='agendado').map(x=>({at:x.doneAt||at(x.date,x.start),k:x.id,ic:'clip',tn:1,t:x.type,d:`${PST[x.status][0]}${x.notes?': '+x.notes:''}`,by:profOf(S,x.prof).name})),
    ...visits.map(v=>({at:at(v.date,v.start),k:v.id,ic:'home',tn:4,t:'Visita domiciliar: '+v.service,d:HVS[v.status][0]+(v.notes?'. '+v.notes:''),by:profOf(S,v.prof).name})),
    ...S.aesAppts.filter(a=>a.patient===id&&a.status==='realizado').map(a=>({at:a.doneAt,k:a.id,ic:'heart',tn:6,t:'Estética: '+aesCatOf(S,a.cat).name,d:a.notes+(a.products?' Produtos: '+a.products+'.':'')+' Termo de consentimento assinado.',by:a.by||profOf(S,a.prof).name})),
    ...S.wounds.filter(w=>w.patient===id).flatMap(w=>w.evals.map(e=>({at:e.at,k:e.id,ic:'activity',tn:5,t:`Avaliação de ${w.type.toLowerCase()} (${w.site.toLowerCase()})`,d:`${e.len} × ${e.wid} × ${e.dep} cm, ${wArea(e).toLocaleString('pt-BR')} cm². Granulação ${e.tissue.gran}%, esfacelo ${e.tissue.esf}%. Exsudato ${e.exudate.toLowerCase()}. ${e.cover}.`,by:e.by}))),
    ...S.ostomies.filter(o=>o.patient===id).flatMap(o=>o.evals.map(e=>({at:e.at,k:e.id,ic:'activity',tn:4,t:'Avaliação de '+o.type.toLowerCase(),d:`Estoma: ${e.aspect.toLowerCase()}. Pele: ${e.peri.toLowerCase()}.${e.teach?' '+e.teach:''}`,by:e.by}))),
    ...S.ltcOcc.filter(o=>o.patient===id).map(o=>({at:o.at,k:o.id,ic:'alert',tn:6,t:'Intercorrência: '+o.kind,d:o.desc+(o.actions?' Condutas: '+o.actions:''),by:o.by}))].filter(x=>x.at).sort((a,b)=>b.at.localeCompare(a.at));
  const tabs=[['tempo','Linha do tempo',tl.length],['vacinas','Caderneta',imm.filter(i=>i.status==='registrado').length],['evol','Evoluções',evol.length],['procs','Procedimentos',procs.length]].concat(can(S,u,'audit.view')?[['acessos','Acessos',access.length]]:[]);
  return html`<div className="space-y-5">
    <div className="flex items-center gap-3"><${IconBtn} n="left" label="Voltar" onClick=${()=>go({page:'prontuario'})} className="bg-panel"/><p className="text-sm text-soft">Prontuário eletrônico</p></div>
    <section className="card-sh overflow-hidden rounded-[26px] bg-panel">
      <div className="h-20" style=${{background:'linear-gradient(110deg,rgb(var(--c-p3)),rgb(var(--c-p2)) 60%,rgb(var(--c-p6)))'}}></div>
      <div className="-mt-10 flex flex-wrap items-end gap-4 px-5 pb-5 sm:px-6"><span className="rounded-full ring-4 ring-panel"><${Avatar} name=${p.name} size=${84}/></span>
        <div className="min-w-0 flex-1"><h1 className="text-[26px] font-semibold leading-tight tracking-tight sm:text-[30px]">${p.name}</h1><p className="text-[14px] text-soft">${ageLabel(p.birth)}${p.birth?', nascimento em '+F(p.birth,{day:'2-digit',month:'2-digit',year:'numeric'}):''}${p.sex?' · '+(p.sex==='F'?'Feminino':'Masculino'):''} · ${p.doc||'Sem documento'}</p>
          <div className="mt-1.5 flex flex-wrap gap-1">${ptTags(p).map(([t,tn])=>html`<${Badge} key=${t} tone=${tn}>${t}<//>`)}</div></div>
        <div className="flex flex-wrap gap-2">${can(S,u,'vaccines.apply')&&p.active&&html`<${Btn} v="lime" icon="syringe" onClick=${()=>go({page:'vacinacao',patient:id})}>Registrar vacina<//>`}${write&&html`<${Btn} v="ink" icon="file" onClick=${()=>setTab('evol')}>Nova evolução<//>`}
          ${write&&html`<${Btn} icon="pencil" onClick=${()=>setEdit(true)}>Editar<//><${Btn} onClick=${()=>run((D,U)=>A.patientActive(D,U,id,!p.active),p.active?'Paciente inativado. O prontuário continua guardado.':'Paciente reativado.')}>${p.active?'Inativar':'Reativar'}<//>`}
          ${can(S,u,'org.manage')&&html`<${Btn} v="danger" icon="trash" onClick=${()=>setDel(true)} aria-label="Excluir paciente"/>`}</div></div>
      <div className="grid gap-px border-t border-line/70 bg-line/50 sm:grid-cols-4">${[['Telefone',p.phone||'Não informado'],['Endereço',p.addr?p.addr+(p.region?', '+p.region:''):'Não informado'],['Responsável',p.guardian||'Não se aplica'],['Cadastro',p.created?F(p.created,{day:'2-digit',month:'2-digit',year:'numeric'}):'—']].map(([k,v])=>html`<div key=${k} className="bg-panel px-5 py-3"><p className="text-[12px] text-faint">${k}</p><p className="truncate text-sm font-semibold">${v}</p></div>`)}</div></section>
    ${(p.allergies.length>0||p.conditions.length>0)&&html`<div className="grid gap-3 md:grid-cols-2">${p.allergies.length>0&&html`<div className="flex items-start gap-3 rounded-[20px] bg-dangerbg p-4 text-danger"><${Icon} n="alert" s=${20} className="shrink-0"/><div><p className="font-bold">Alergias informadas</p><p className="text-sm">${p.allergies.join(' · ')}</p></div></div>`}
      ${p.conditions.length>0&&html`<div className="flex items-start gap-3 rounded-[20px] bg-p5 p-4 text-onp"><${Icon} n="heart" s=${20} className="shrink-0"/><div><p className="font-bold">Condições informadas</p><p className="text-sm">${p.conditions.join(' · ')}</p></div></div>`}</div>`}
    <${Card} pad=${false}><div className="px-3 pt-2 sm:px-5"><${MiniTabs} items=${tabs} value=${tab} onChange=${setTab}/></div><div className="p-5 sm:p-6">
      ${tab==='tempo'&&(tl.length?html`<ol className="relative space-y-3 border-l-2 border-line pl-6">${tl.map(x=>html`<li key=${x.k} className=${cx('relative',x.off&&'opacity-50')}><span className=${cx('absolute -left-[43px] grid h-9 w-9 place-items-center rounded-xl text-onp ring-4 ring-panel',PASTEL[x.tn])}><${Icon} n=${x.ic} s=${16}/></span>
          <div className="rounded-[18px] bg-panel2 px-4 py-3"><div className="flex flex-wrap items-baseline justify-between gap-2"><p className="font-bold">${x.t}${x.off?' (cancelada)':''}</p><p className="text-[12px] text-faint">${F(x.at,{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}</p></div><p className="mt-0.5 text-sm text-soft">${x.d}</p>${x.by&&html`<p className="mt-1 text-[12px] text-faint">${x.by}</p>`}</div></li>`)}</ol>`:html`<${Empty} title="Sem registros ainda"/>`)}
      ${tab==='vacinas'&&html`<div className="space-y-5">
        ${status&&html`<div><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">Situação pelo calendário da criança</h3><button className="text-sm font-semibold text-skyink hover:underline" onClick=${()=>go({page:'calendario'})}>Abrir calendário vacinal</button></div>
          <div className="no-scrollbar -mx-1 flex gap-3 overflow-x-auto px-1 pb-2">${status.filter(r=>r.items.some(i=>i.core)).map(r=>html`<div key=${r.age} className="w-[190px] shrink-0 rounded-[18px] border border-line/70 p-3"><p className="text-sm font-bold">${r.age}</p><p className="mb-2 text-[11.5px] text-faint">${F(addMonthsKey(p.birth,r.m),{day:'2-digit',month:'2-digit',year:'2-digit'})}</p>
            <div className="space-y-1.5">${r.items.filter(i=>i.core).map(i=>html`<div key=${i.v+i.dose} className="flex items-center gap-2 text-[12.5px]"><${Dot} tone=${CST[i.st][1]}/><span className="min-w-0 flex-1 truncate"><b>${VAC[i.v].n}</b> ${i.dose}</span></div>`)}</div></div>`)}</div>
          <div className="mt-2 flex flex-wrap gap-3 text-[12px] text-soft">${['aplicada','agora','atrasada','prevista','janela'].map(k=>html`<span key=${k} className="inline-flex items-center gap-1.5"><${Dot} tone=${CST[k][1]}/>${CST[k][0]}</span>`)}</div></div>`}
        <div className="flex flex-wrap items-center justify-between gap-2"><h3 className="font-bold">Doses registradas</h3>${can(S,u,'vaccines.apply')&&html`<${Btn} size="sm" icon="plus" onClick=${()=>setExt(true)}>Transcrever dose<//>`}</div>
        <${Table} minW=${720} cols=${['Data','Vacina','Dose','Lote','Via e local','Origem']} empty="Nenhuma dose registrada" rows=${imm.map(i=>html`<tr key=${i.id} className=${i.status==='cancelado'?'opacity-50 line-through':''}>
          <${TD} className="whitespace-nowrap">${F(i.at,{day:'2-digit',month:'2-digit',year:'numeric'})}<//><${TD}><span className="inline-flex items-center gap-2"><span className=${cx('h-3 w-3 rounded',PASTEL[VAC[i.vac].c])}></span><b>${VAC[i.vac].n}</b></span><//><${TD}>${i.dose}<//>
          <${TD}>${i.lot?lotOf(S,i.lot).lot:i.lotText||'—'}<//><${TD} className="text-soft">${i.via}, ${i.site.toLowerCase()}<//><${TD}>${i.origin==='externa'?html`<${Badge} tone="p1">Transcrita<//><span className="block text-[11.5px] text-faint">${i.place}</span>`:html`<${Badge} tone="p4">Aplicada aqui<//><span className="block text-[11.5px] text-faint">${i.prof?profOf(S,i.prof).name:''}</span>`}<//></tr>`)}/></div>`}
      ${tab==='evol'&&html`<div className="space-y-4">${write&&p.active&&html`<div className="rounded-[20px] bg-panel2 p-4"><div className="mb-3 flex flex-wrap gap-1.5">${EV_KIND.map(k=>html`<button key=${k} onClick=${()=>setEv({...ev,kind:k})} className=${cx('rounded-full px-3 py-1.5 text-[13px] font-semibold',ev.kind===k?'bg-navy text-onnavy':'bg-panel')}>${k}</button>`)}</div>
          <textarea className=${inputCls+' min-h-[110px] bg-panel'} aria-label="Texto da evolução" placeholder="Descreva o atendimento de forma objetiva: o que foi observado, o que foi feito e as orientações dadas." value=${ev.text} onInput=${e=>setEv({...ev,text:e.target.value})}></textarea>
          <div className="mt-3 flex flex-wrap items-center justify-between gap-2"><p className="flex items-center gap-1.5 text-[12px] text-faint"><${Icon} n="lock" s=${12}/>Depois de assinado, o registro não pode ser editado nem apagado. Correções viram adendo.</p>
            <${Btn} v="lime" icon="check" disabled=${ev.text.trim().length<10} onClick=${()=>{const r=run((D,U)=>A.record(D,U,{patient:id,...ev}),'Evolução assinada e registrada.');if(r.ok)setEv({...ev,text:''})}}>Assinar e registrar<//></div></div>`}
        ${evol.length===0?html`<${Empty} title="Nenhuma evolução registrada"/>`:html`<ul className="space-y-3">${evol.map(e=>html`<li key=${e.id} className="rounded-[20px] border border-line/70 p-4"><div className="flex items-start gap-3"><${Avatar} name=${e.author} size=${36}/><div className="min-w-0 flex-1">
          <div className="flex flex-wrap items-center gap-2"><p className="font-bold">${e.author}</p><span className="text-[12px] text-faint">${e.cat}</span><${Badge} tone="p2">${e.kind}<//><span className="ml-auto text-[12px] text-faint">${F(e.at,{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}</span></div>
          <p className="mt-1.5 whitespace-pre-wrap text-[14.5px]">${e.text}</p>
          ${e.addenda.map((a,i)=>html`<div key=${i} className="mt-2 rounded-xl bg-p1/40 px-3 py-2 text-sm"><b>Adendo</b> <span className="text-[12px] text-faint">${F(a.at,{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span><p>${a.text}</p></div>`)}
          ${e.author===u.name&&(ad===e.id?html`<div className="mt-2 flex flex-wrap gap-2"><input className=${inputCls+' h-10 flex-1 py-1.5'} placeholder="Texto do adendo" aria-label="Adendo" value=${adT} onInput=${x=>setAdT(x.target.value)}/><${Btn} size="sm" onClick=${()=>setAd(null)}>Voltar<//><${Btn} size="sm" v="lime" onClick=${()=>{const r=run((D,U)=>A.addendum(D,U,e.id,adT),'Adendo registrado.');if(r.ok){setAd(null);setAdT('')}}}>Salvar adendo<//></div>`
            :html`<button className="mt-2 text-[13px] font-semibold text-soft hover:text-ink" onClick=${()=>{setAd(e.id);setAdT('')}}>Acrescentar adendo</button>`)}</div></div></li>`)}</ul>`}</div>`}
      ${tab==='procs'&&(procs.length?html`<ul className="space-y-2">${procs.map(x=>html`<li key=${x.id} className="flex flex-wrap items-center gap-3 rounded-[18px] bg-panel2 px-4 py-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-p1 text-onp"><${Icon} n="clip" s=${16}/></span>
          <span className="min-w-0 flex-1"><span className="block font-bold">${x.type}</span><span className="block text-[12.5px] text-soft">${F(x.date,{day:'2-digit',month:'2-digit',year:'numeric'})} ${x.start} · ${profOf(S,x.prof).name}${x.notes?' · '+x.notes:''}</span>${x.verifiedBy&&html`<span className="block text-[12px] text-faint">Conferido por ${x.verifiedBy}</span>`}</span><${Badge} tone=${PST[x.status][1]}>${PST[x.status][0]}<//></li>`)}</ul>`:html`<${Empty} title="Nenhum procedimento"/>`)}
      ${tab==='acessos'&&html`<div><p className="mb-3 text-sm text-soft">Quem acessou ou alterou este prontuário. Registro exigido para rastreabilidade (LGPD).</p><${Table} minW=${560} cols=${['Quando','Quem','Ação','Detalhe']} rows=${access.map(a=>html`<tr key=${a.id}><${TD} className="whitespace-nowrap">${F(a.at,{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}<//><${TD}><span className="flex items-center gap-2"><${Avatar} name=${a.actor} size=${24}/>${a.actor}</span><//><${TD} className="font-semibold">${ACT[a.action]||a.action}<//><${TD} className="text-soft">${a.detail}<//></tr>`)}/></div>`}
    </div><//>
    ${edit&&html`<${PatientForm} p=${p} onClose=${()=>setEdit(false)} onSaved=${()=>setEdit(false)}/>`}
    ${ext&&html`<${ExternalDose} patient=${id} onClose=${()=>setExt(false)}/>`}
    <${Confirm} open=${del} title="Excluir paciente" desc="Só é possível excluir cadastros sem nenhum registro clínico. Com registros, o prontuário precisa ser guardado: use Inativar." onClose=${()=>setDel(false)} onOk=${()=>{const r=run((D,U)=>A.patientDelete(D,U,id),'Paciente excluído.');setDel(false);if(r.ok)go({page:'prontuario'})}}/></div>`;
}

/* ------------------------------------------------------------------ procedimentos (gestão e conferência) */
const PCOL=[['agendado','Agendados',3],['realizado','Aguardando conferência',1],['devolvido','Devolvidos para correção',6],['conferido','Conferidos',4]];
function ProcAssign({onClose}){
  const {S,run}=useApp();const [f,setF]=useState({patient:'',type:(S.procCat.find(p=>!p.archived)||{}).name||'',prof:'',date:today(),start:'10:00',unit:S.units[0].id});
  return html`<${Modal} open wide onClose=${onClose} title="Agendar procedimento" desc="O profissional recebe o aviso e confirma a realização pela Minha área. Depois, a responsável técnica confere."
    footer=${html`<${Btn} onClick=${onClose}>Cancelar<//><${Btn} v="lime" onClick=${()=>{const r=run((D,U)=>A.procAssign(D,U,f),'Procedimento agendado e profissional avisado.');if(r.ok)onClose()}}>Agendar<//>`}>
    <div className="grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><p className="mb-1.5 text-[13px] font-semibold text-soft">Paciente</p><${PatientPicker} id="pa-p" value=${f.patient} onChange=${id=>setF({...f,patient:id})}/></div>
      <${Field} label="Procedimento" id="pa-t"><select id="pa-t" className=${inputCls} value=${f.type} onChange=${e=>setF({...f,type:e.target.value})}>${S.procCat.filter(p=>!p.archived).map(p=>html`<option key=${p.id}>${p.name}</option>`)}</select><//>
      <${Field} label="Profissional" id="pa-pr"><select id="pa-pr" className=${inputCls} value=${f.prof} onChange=${e=>setF({...f,prof:e.target.value})}><option value="">Selecione</option>${S.profs.filter(p=>p.active&&p.cat!=='medico'&&p.cat!=='farmaceutico').map(p=>html`<option key=${p.id} value=${p.id}>${p.name}</option>`)}</select><//>
      <${Field} label="Data" id="pa-d"><input id="pa-d" type="date" className=${inputCls} value=${f.date} onChange=${e=>setF({...f,date:e.target.value})}/><//>
      <${Field} label="Horário" id="pa-h"><input id="pa-h" type="time" className=${inputCls} value=${f.start} onChange=${e=>setF({...f,start:e.target.value})}/><//>
      <${Field} label="Unidade" id="pa-u"><select id="pa-u" className=${inputCls} value=${f.unit} onChange=${e=>setF({...f,unit:e.target.value})}>${S.units.filter(x=>!x.archived).map(x=>html`<option key=${x.id} value=${x.id}>${x.name}</option>`)}</select><//></div><//>`;
}
function Procedimentos(){
  const {S,u,run}=useApp();const T=today();const [prof,setProf]=useState('');const [per,setPer]=useState('semana');const [nw,setNw]=useState(false);const [back,setBack]=useState(null);
  const verify=can(S,u,'procedures.verify');
  const list=S.procs.filter(x=>(!prof||x.prof===prof)&&(per==='todos'||(per==='hoje'?x.date===T:x.date>=addDays(T,-6))));
  const col=k=>list.filter(x=>k==='realizado'?(x.status==='realizado'||x.status==='nao_realizado'):x.status===k).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
  return html`<div className="space-y-5"><${PageHead} title="Procedimentos" desc="O profissional registra e confirma o que realizou; a responsável técnica confere ou devolve para correção. Tudo entra no prontuário."
    actions=${(verify||can(S,u,'homecare.manage'))&&html`<${Btn} v="lime" icon="plus" onClick=${()=>setNw(true)}>Agendar procedimento<//>`}/>
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">${PCOL.map(([k,l,tn])=>html`<${Kpi} key=${k} icon=${k==='conferido'?'check':k==='devolvido'?'left':k==='realizado'?'clock':'cal'} tone=${tn} title=${l} sub=${per==='hoje'?'Hoje':per==='semana'?'Últimos 7 dias':'Todos'} value=${col(k).length}/>`)}</div>
    <div className="flex flex-wrap items-center gap-2"><${Seg} size="sm" items=${[['hoje','Hoje'],['semana','7 dias'],['todos','Todos']]} value=${per} onChange=${setPer}/>
      <select aria-label="Profissional" className=${selCls+' card-sh h-10 sm:ml-auto'} value=${prof} onChange=${e=>setProf(e.target.value)}><option value="">Todos os profissionais</option>${S.profs.filter(p=>S.procs.some(x=>x.prof===p.id)).map(p=>html`<option key=${p.id} value=${p.id}>${p.name}</option>`)}</select></div>
    <div className="no-scrollbar -mx-4 overflow-x-auto px-4 pb-2"><div className="grid min-w-[1000px] grid-cols-4 gap-4">${PCOL.map(([k,l,tn])=>{const xs=col(k);return html`<section key=${k} className="rounded-[22px] bg-panel/60 p-2.5 ring-1 ring-line/70">
      <header className="flex items-center justify-between px-2 pb-2.5 pt-1"><span className="flex items-center gap-2 text-sm font-bold"><span className=${cx('h-2.5 w-2.5 rounded-full',PASTEL[tn])}></span>${l}</span><span className="rounded-full bg-panel2 px-2 text-[12px] font-bold">${xs.length}</span></header>
      <div className="space-y-2.5">${xs.length===0?html`<p className="rounded-2xl border border-dashed border-line px-3 py-6 text-center text-[13px] text-faint">Nada aqui</p>`:xs.map(x=>{const pt=patOf(S,x.patient),pr=profOf(S,x.prof);return html`<article key=${x.id} className=${cx('rounded-[18px] p-3.5 text-onp',PASTEL[tn])}>
        <div className="flex flex-wrap gap-1"><span className="rounded-full bg-white/70 px-2 py-0.5 text-[11px] font-bold">#${x.type.split(' ')[0].toLowerCase()}</span><span className="rounded-full bg-white/70 px-2 py-0.5 text-[11px] font-bold">${D2(x.date)} ${x.start}</span>${x.status==='nao_realizado'&&html`<span className="rounded-full bg-white px-2 py-0.5 text-[11px] font-bold text-danger">não realizado</span>`}</div>
        <p className="mt-2 font-bold leading-tight">${x.type}</p><p className="text-[13px] opacity-80">${pt.name}</p>
        ${x.notes&&html`<p className="mt-1.5 line-clamp-3 rounded-xl bg-white/55 px-2.5 py-1.5 text-[12.5px]">${x.notes}</p>`}${x.returnNote&&html`<p className="mt-1.5 rounded-xl bg-white/80 px-2.5 py-1.5 text-[12.5px]"><b>Correção pedida:</b> ${x.returnNote}</p>`}
        <div className="mt-3 flex items-center gap-2"><${Avatar} name=${pr.name} size=${26}/><span className="min-w-0 flex-1 truncate text-[12.5px] font-semibold">${pr.name}</span>${x.verifiedBy&&html`<span className="text-[11px] opacity-70">por ${x.verifiedBy.split(' ')[0]}</span>`}</div>
        ${verify&&k==='realizado'&&html`<div className="mt-3 flex gap-2"><button className="h-8 flex-1 rounded-full bg-[#111318] text-[12.5px] font-bold text-white" onClick=${()=>run((D,U)=>A.procVerify(D,U,x.id,true),'Procedimento conferido.')}>Conferir</button><button className="h-8 flex-1 rounded-full bg-white/80 text-[12.5px] font-bold" onClick=${()=>setBack(x)}>Devolver</button></div>`}</article>`})}</div></section>`})}</div></div>
    ${nw&&html`<${ProcAssign} onClose=${()=>setNw(false)}/>`}
    <${Confirm} open=${!!back} title="Devolver para correção" desc=${back?`${back.type}, ${patOf(S,back.patient).name}. O profissional recebe o aviso e corrige pela Minha área.`:''} okLabel="Devolver" tone="ink" needReason onClose=${()=>setBack(null)} onOk=${r=>{const x=run((D,U)=>A.procVerify(D,U,back.id,false,r),'Procedimento devolvido.');if(x.ok)setBack(null)}}/></div>`;
}
